import{_ as e,c as a,o as l,ae as i}from"./chunks/framework.DI6M9D4h.js";const r="/assets/lipo-301230.DcWikFuQ.jpg",n="/assets/puchi-ble-pinout.DfevTFiT.png",s="/assets/puchi-ble-schematic.Bdku6jls.png",P=JSON.parse('{"title":"Puchi-BLE","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/puchi-ble/index.md","filePath":"build-guides/puchi-ble/index.md","lastUpdated":1754313574000}'),d={name:"build-guides/puchi-ble/index.md"};function o(c,t,h,g,p,y){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="puchi-ble" tabindex="-1">Puchi-BLE <a class="header-anchor" href="#puchi-ble" aria-label="Permalink to &quot;Puchi-BLE&quot;">​</a></h1><p><a href="https://github.com/firstcontributions/first-contributions" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/PRs-welcome-brightgreen.svg?style=flat-square" alt="PRs Welcome" loading="lazy"></a> <a href="https://discord.gg/frjFXZB" title="Redirect to Keycapsss Discord" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/548530462419582996?style=flat-square&amp;logo=discord&amp;logoColor=white" alt="Discord" loading="lazy"></a> <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/License-CC%20BY--NC--SA%204.0-lightgrey.svg?style=flat-square" alt="License: CC BY-NC-SA 4.0" loading="lazy"></a></p><h2 id="todo" tabindex="-1">ToDo <a class="header-anchor" href="#todo" aria-label="Permalink to &quot;ToDo&quot;">​</a></h2><p><strong>Please help to improve this guide. Edit the page <a href="https://github.com/Keycapsss/puchi-ble/edit/main/README.md" target="_blank" rel="noreferrer">here</a>.</strong></p><ul><li>[ ] Status Led‘s (blue solid state)</li><li>Bootloader <ul><li>[x] Which and what changes</li><li>[x] How to enter bootloader mode</li></ul></li><li>[x] Pinout</li><li>[x] How to compile/use <a href="https://zmk.dev/" target="_blank" rel="noreferrer">ZMK</a></li><li>[x] Create a ZMK Puchi-BLE board</li><li>[ ] How to compile/use QMK <a href="https://github.com/sekigon-gonnoc/qmk_firmware/tree/nrf52" target="_blank" rel="noreferrer">nrf52 fork</a></li><li>[x] How to flash a firmware</li><li>[x] What batteries are supported</li></ul><h2 id="battery-read-carefully" tabindex="-1">Battery (read carefully) <a class="header-anchor" href="#battery-read-carefully" aria-label="Permalink to &quot;Battery (read carefully)&quot;">​</a></h2><ul><li>Puchi-BLE supports 1S LiPo batteries (4.2V)</li><li>Only use LiPo batteries with a protection circuit, because the Puchi-BLE has no low voltes (discharge) protection for batteries <img src="'+r+'" alt="LiPo battery 301230 with protection circuit" loading="lazy"></li><li>A 301230 (3.0 x 12 x 30 mm) LiPo battery fit between 4.5mm tall pin sockets</li><li>Connect the battery to B+ (red) and B- (black ), or RAW (red) and GND (black) (these pairs of pins are internally connected)</li><li><strong>Avoid reverse polarity</strong> (nRF52840 chip is usually destroyed first)</li><li><strong>Note that a few keyboards have RAW and VCC pins connected together (namely Helix and Gherkin), and will kill the controller</strong> (RAW pin is for the charger only). You may just not solder RAW pin to the keyboard as a workaround.</li></ul><blockquote><p>I don&#39;t offer LiPo batteries in the shop, because of the German strict law.</p></blockquote><h2 id="bootloader" tabindex="-1">Bootloader <a class="header-anchor" href="#bootloader" aria-label="Permalink to &quot;Bootloader&quot;">​</a></h2><p>A customized <a href="https://github.com/adafruit/Adafruit_nRF52_Bootloader/releases" target="_blank" rel="noreferrer">Adafruit nRF52 Bootloader</a> is flashed on the Puchi-BLE.</p><p><a href="https://gist.github.com/joric/7226eda8d5fdba44bc64d4520825a11d" target="_blank" rel="noreferrer">Here</a> you can find the changes from the original Adafruit nRF52 Bootloader.</p><p>The Bootloader binary already contain the Bluetooth stack (a.k.a SoftDevice).</p><h3 id="how-to-enter-the-bootloader-mode" tabindex="-1">How to enter the bootloader mode <a class="header-anchor" href="#how-to-enter-the-bootloader-mode" aria-label="Permalink to &quot;How to enter the bootloader mode&quot;">​</a></h3><p>Press RESET (short RST with GND) twice within 500ms.<br> The blue led will start slowly dimming and a Mass Storage (NRF52BOOT) should appear in your file explorer.</p><p>Now you can copy the ZMK UF2 firmware file on it. After copying the UF2 file to the Mass Storage, the Puchi-BLE will automatically reboot and load the new firmware.</p><h2 id="status-led-s" tabindex="-1">Status Led&#39;s <a class="header-anchor" href="#status-led-s" aria-label="Permalink to &quot;Status Led&#39;s&quot;">​</a></h2><ul><li>Red solid: power connected</li><li>Blue 2x blinking: restart</li><li>Blue slow flashing (every 3sec): <s>waiting for bluetooth connection</s></li><li>Blue fast flashing:</li><li>Blue off: <s>connected via bluetooth</s></li><li>Blue slow dimming: USB Mass Storage mode, for firmware update</li><li>Blue solid: ?</li></ul><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><h3 id="zmk" tabindex="-1">ZMK <a class="header-anchor" href="#zmk" aria-label="Permalink to &quot;ZMK&quot;">​</a></h3><p><a href="https://zmk.dev/docs/development/" target="_blank" rel="noreferrer">Setup local ZMK environment</a> (with VS Code &amp; Docker is the easiest), or use the <a href="https://zmk.dev/docs/user-setup" target="_blank" rel="noreferrer">Github action method</a>.</p><p>Build UF2 firmware file for Corne left side ...</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">west</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/left</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puchi_ble_v1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DSHIELD=corne_left</span></span></code></pre></div><p>After a successful build, you can find the UF2 firmware file in the <code>app/build/left/zephyr/zmk.uf2</code> folder.</p><p>... and right side.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">west</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/right</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> puchi_ble_v1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DSHIELD=corne_right</span></span></code></pre></div><p>More information about &#39;Building For Split Keyboards&#39; <a href="https://zmk.dev/docs/development/build-flash#building-for-split-keyboards" target="_blank" rel="noreferrer">here</a>.</p><p><a href="https://github.com/Keycapsss/puchi-ble/tree/main/firmware" target="_blank" rel="noreferrer">Here</a> you can find the precompiled firmware files (UF2) for the Corne and Lily58 keyboard.</p><h3 id="qmk-nrf52-branch" tabindex="-1">QMK (nrf52 branch) <a class="header-anchor" href="#qmk-nrf52-branch" aria-label="Permalink to &quot;QMK (nrf52 branch)&quot;">​</a></h3><p><a href="https://github.com/joric/nrfmicro/wiki/QMK" target="_blank" rel="noreferrer">Detailed documentation</a> by Joric</p><h2 id="pinout" tabindex="-1">Pinout <a class="header-anchor" href="#pinout" aria-label="Permalink to &quot;Pinout&quot;">​</a></h2><p><img src="'+n+'" alt="Puchi-BLE pinout diagram" loading="lazy"></p><h3 id="controller-pinout-comparison" tabindex="-1">Controller pinout comparison <a class="header-anchor" href="#controller-pinout-comparison" aria-label="Permalink to &quot;Controller pinout comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Puchi-BLE</th><th style="text-align:center;">nRFMicro 1.3+</th><th style="text-align:center;">nice!nano</th><th style="text-align:center;">ProMicro</th><th style="text-align:center;">Left</th><th style="text-align:center;">Right</th><th style="text-align:center;">ProMicro</th><th style="text-align:center;">nice!nano</th><th style="text-align:center;">nRFMicro 1.3+</th><th style="text-align:center;">Puchi-BLE</th></tr></thead><tbody><tr><td style="text-align:center;">P0.06</td><td style="text-align:center;">P0.06</td><td style="text-align:center;">P0.06</td><td style="text-align:center;">D3</td><td style="text-align:center;">PIN1</td><td style="text-align:center;">PIN24</td><td style="text-align:center;">RAW</td><td style="text-align:center;">RAW</td><td style="text-align:center;">RAW</td><td style="text-align:center;">RAW</td></tr><tr><td style="text-align:center;">P0.08</td><td style="text-align:center;">P0.08</td><td style="text-align:center;">P0.08</td><td style="text-align:center;">D2</td><td style="text-align:center;">PIN2</td><td style="text-align:center;">PIN23</td><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td></tr><tr><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td><td style="text-align:center;">PIN3</td><td style="text-align:center;">PIN22</td><td style="text-align:center;">RST</td><td style="text-align:center;">P0.18</td><td style="text-align:center;">P0.18</td><td style="text-align:center;">P0.18</td></tr><tr><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td><td style="text-align:center;">GND</td><td style="text-align:center;">PIN4</td><td style="text-align:center;">PIN21</td><td style="text-align:center;">VCC</td><td style="text-align:center;">VCC</td><td style="text-align:center;">VCC</td><td style="text-align:center;">VCC</td></tr><tr><td style="text-align:center;">P0.15</td><td style="text-align:center;">P0.15</td><td style="text-align:center;">P0.17</td><td style="text-align:center;">D1</td><td style="text-align:center;">PIN5</td><td style="text-align:center;">PIN20</td><td style="text-align:center;">F4</td><td style="text-align:center;">P0.31</td><td style="text-align:center;">P0.30</td><td style="text-align:center;">P0.30</td></tr><tr><td style="text-align:center;">P0.17</td><td style="text-align:center;">P0.17</td><td style="text-align:center;">P0.20</td><td style="text-align:center;">D0</td><td style="text-align:center;">PIN6</td><td style="text-align:center;">PIN19</td><td style="text-align:center;">F5</td><td style="text-align:center;">P0.29</td><td style="text-align:center;">P0.31</td><td style="text-align:center;">P0.31</td></tr><tr><td style="text-align:center;">P0.20</td><td style="text-align:center;">P0.20</td><td style="text-align:center;">P0.22</td><td style="text-align:center;">D4</td><td style="text-align:center;">PIN7</td><td style="text-align:center;">PIN18</td><td style="text-align:center;">F6</td><td style="text-align:center;">P0.02</td><td style="text-align:center;">P0.29</td><td style="text-align:center;">P0.29</td></tr><tr><td style="text-align:center;">P0.13</td><td style="text-align:center;">P0.13</td><td style="text-align:center;">P0.24</td><td style="text-align:center;">C6</td><td style="text-align:center;">PIN8</td><td style="text-align:center;">PIN17</td><td style="text-align:center;">F7</td><td style="text-align:center;">P1.15</td><td style="text-align:center;">P0.02</td><td style="text-align:center;">P0.02</td></tr><tr><td style="text-align:center;">P0.24</td><td style="text-align:center;">P0.24</td><td style="text-align:center;">P1.00</td><td style="text-align:center;">D7</td><td style="text-align:center;">PIN9</td><td style="text-align:center;">PIN16</td><td style="text-align:center;">B1</td><td style="text-align:center;">P1.13</td><td style="text-align:center;">P1.13</td><td style="text-align:center;">P1.13</td></tr><tr><td style="text-align:center;">P0.09</td><td style="text-align:center;">P0.09</td><td style="text-align:center;">P0.11</td><td style="text-align:center;">E6</td><td style="text-align:center;">PIN10</td><td style="text-align:center;">PIN15</td><td style="text-align:center;">B3</td><td style="text-align:center;">P1.11</td><td style="text-align:center;">P0.03</td><td style="text-align:center;">P0.03</td></tr><tr><td style="text-align:center;">P0.10</td><td style="text-align:center;">P0.10</td><td style="text-align:center;">P1.04</td><td style="text-align:center;">B4</td><td style="text-align:center;">PIN11</td><td style="text-align:center;">PIN14</td><td style="text-align:center;">B2</td><td style="text-align:center;">P0.10</td><td style="text-align:center;">P0.28</td><td style="text-align:center;">P0.28</td></tr><tr><td style="text-align:center;">P1.06</td><td style="text-align:center;">P1.06</td><td style="text-align:center;">P1.06</td><td style="text-align:center;">B5</td><td style="text-align:center;">PIN12</td><td style="text-align:center;">PIN13</td><td style="text-align:center;">B6</td><td style="text-align:center;">P0.09</td><td style="text-align:center;">P1.11</td><td style="text-align:center;">P1.11</td></tr></tbody></table><h3 id="service-pins" tabindex="-1">Service Pins <a class="header-anchor" href="#service-pins" aria-label="Permalink to &quot;Service Pins&quot;">​</a></h3><ul><li>P0.18 - RESET</li><li>P1.10 - BLUE_LED (P0.15 on nice!nano)</li><li>P1.09 - POWER_PIN (EXT_VCC control, P0.13 on nice!nano) (1-off, 0-on)</li><li>P0.04 - BATTERY_PIN (analog battery voltage in mV, 820kΩ/2MΩ)</li></ul><h3 id="low-drive-low-frequency-pins" tabindex="-1">Low drive (low frequency) pins <a class="header-anchor" href="#low-drive-low-frequency-pins" aria-label="Permalink to &quot;Low drive (low frequency) pins&quot;">​</a></h3><p>P0.31, P0.29, P0.02, P1.15, P1.13, P1.10, P0.30, P0.28, P0.03, P1.14, P1.12, P1.11, P0.10, P0.09, P1.07, P1.06, P1.05, P1.04, P1.03, P1.02, P1.01</p><h3 id="normal-high-frequency-pins" tabindex="-1">Normal (high frequency) pins <a class="header-anchor" href="#normal-high-frequency-pins" aria-label="Permalink to &quot;Normal (high frequency) pins&quot;">​</a></h3><p>P0.00, P0.01, P0.26, P0.27, P0.04, P0.05, P0.06, P0.07, P0.08, P1.08, P1.09, P0.11, P0.12, P0.14, P0.16, P0.18, P0.19, P0.21, P0.23, P0.25, P0.13, P0.15, P0.17, P0.20, P0.22, P0.24, P1.00</p><p>Detailed pin information can be found on the <a href="https://infocenter.nordicsemi.com/topic/ps_nrf52840/pin.html?cp=4_0_0_6_0_1#qfn48" target="_blank" rel="noreferrer">Nordic Infocenter</a>.</p><h2 id="schematic" tabindex="-1">Schematic <a class="header-anchor" href="#schematic" aria-label="Permalink to &quot;Schematic&quot;">​</a></h2><p><img src="'+s+'" alt="Puchi-BLE schematic" loading="lazy"></p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><ul><li>Do i need a TRRS cable to connect the split keyboard halfs? <ul><li>No, the slave side connects wireless to the master side. Optional you can use a cable (no charge over TRRS cable).</li></ul></li><li>What&#39;s the battery life? <ul><li>Approximately 2weeks with a 100mAh battery (no oled, or led‘s).</li></ul></li><li>Is there a lag while typing? <ul><li>Bluetooth devices can reach a latency of 1.3 ms. Lower latency means more power drain and reduce the battery life.</li></ul></li><li>Is it possible to switch between Bluetooth devices? <ul><li>Yes, QMK and ZMK have support for up to 5 Bluetooth profiles.</li></ul></li><li>What batteries work with the Puchi-BLE? <ul><li>LiPo batteries with 1S. Also important is that the LiPo batterie has a protection circuit</li></ul></li><li>Are batteries available in the shop? <ul><li>No, due to the german law, i don’t offer batteries in the shop. You can get LiPo batteries on Ebay and Aliexpress.</li></ul></li><li>What are the EXT_VCC and EXT_GND? Are they the same pins as VCC and GND? <ul><li>Yes. Power output is sofware-controlled to save battery (RGB LEDs draw up to 1 mA each when off).</li></ul></li></ul>',44)])])}const x=e(d,[["render",o]]);export{P as __pageData,x as default};
